package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;import org.w3c.dom.Element;
/** Synthetic destination chooser; no request is an implicit Move. */
final class ManagerChooserChecks {
 final MapAndroidChecks m;final ManagerVisualChecks v;final ManagerRotationChecks r;final ManagerMoveChecks c;
 ManagerChooserChecks(MapAndroidChecks m){this.m=m;v=new ManagerVisualChecks(m);r=new ManagerRotationChecks(m);c=new ManagerMoveChecks(m);}
 void open(long id)throws Exception{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);m.check(m.activity.getResources().getConfiguration().orientation==1,"chooser starts in settled portrait");m.waitText("QA_ROTATE_OTHER");m.click("QA_ROTATE_POINT");m.click("QA_ROTATE_OTHER");m.setListingForm("QA_ROTATE_POINT",0,0,0,false,false,0);m.managerAction("Перенести выбранное");m.waitText("Перенести в папку");}
 void identity(long id,String token)throws Exception{Object d=m.managerField("chooserDraft");m.check(d!=null,"original chooser draft retained");Class<?> t=d.getClass();m.check(t.getField("project").getLong(d)==id&&token.equals(t.getField("token").get(d))&&"".equals(t.getField("destination").get(d))&&t.getField("outside").getInt(d)==1,"chooser keeps original project/token/no destination/hidden count");m.check(Arrays.equals((int[])t.getMethod("indices").invoke(d),new int[]{2,3}),"chooser keeps original compact sources");}
 void rotate(int direction,long id,String token,String scene,boolean valid)throws Exception{Activity old=m.activity;v.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"chooser Activity actually destroyed: "+scene);m.check(m.visibleText("Перенести в папку"),"open chooser survives actual recreation");identity(id,token);v.controlReachable("Отмена");m.check(valid?m.visibleText("Корень проекта / QA_ROTATE_FOLDER"):m.visibleText("Выбор папки заблокирован"),"choices available only for unchanged original XML");v.snapshot(scene,false);}
 void unchanged(Object store,long id,byte[] xml,Map<String,byte[]> assets,Map<String,?> prefs)throws Exception{m.check(Arrays.equals(xml,r.xml(r.load(store,id)))&&prefs.equals(c.prefs()),"chooser Cancel/rejection preserves XML and all applied settings");r.sameAssets(r.load(store,id),assets);}
 void dismissed()throws Exception{m.check(m.managerField("chooserDraft")==null&&m.managerField("moveDraft")==null,"Cancel/success removes chooser and confirmation");Activity old=m.activity;v.rotate(m.activity.getResources().getConfiguration().orientation==1?UiAutomation.ROTATION_FREEZE_90:UiAutomation.ROTATION_FREEZE_0);m.check(old!=m.activity&&old.isDestroyed(),"dismissed chooser main actually recreated");m.check(m.managerField("chooserDraft")==null&&m.managerField("moveDraft")==null,"dismissed chooser never reopens");}
 void scenario(Object store,String outcome)throws Exception{long id=c.insert(store);try{open(id);Object doc=r.load(store,id);byte[] xml=r.xml(doc);String token=m.treeToken(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));Map<String,?> prefs=c.prefs();identity(id,token);if(outcome.equals("cancel"))v.snapshot("chooser-before",false);if(outcome.equals("stale-before"))r.externalChange(store,id,true);byte[] current=r.xml(r.load(store,id));rotate(UiAutomation.ROTATION_FREEZE_90,id,token,"chooser-"+outcome,!outcome.equals("stale-before"));m.check(Arrays.equals(current,r.xml(r.load(store,id))),"recreating chooser never moves objects");r.sameAssets(r.load(store,id),assets);
  if(outcome.equals("cancel")){m.check(new HashSet<>(m.managerKeys("selected")).equals(c.chosen),"chooser visible/hidden selection survives");rotate(UiAutomation.ROTATION_FREEZE_0,id,token,"chooser-return",true);m.click("Отмена");unchanged(store,id,xml,assets,prefs);}
  else if(outcome.equals("stale-before")){m.check(m.managerKeys("selected").isEmpty(),"shifted XML never rebinds chooser source indices");Map<String,?> now=c.prefs();m.click("Отмена");unchanged(store,id,current,assets,now);}
  else{if(outcome.equals("stale-after"))r.externalChange(store,id,false);byte[] newer=r.xml(r.load(store,id));m.click("Корень проекта / QA_ROTATE_FOLDER");c.identity(id,token);m.check(m.managerField("chooserDraft")==null,"choosing destination closes chooser intent");m.check(Arrays.equals(newer,r.xml(r.load(store,id))),"choosing a destination still requires explicit Move");
   if(outcome.equals("choice-cancel")){m.click("Отмена");unchanged(store,id,xml,assets,prefs);}
   else if(outcome.equals("save")){c.rotate(UiAutomation.ROTATION_FREEZE_0,"chooser-confirm-return",id,token,true);Object expected=r.parse(xml);m.staticCall("ObjectTree","move",new Class[]{Element.class,Collection.class,String.class,String.class},m.call(expected,"root",new Class[]{}),new ArrayList<>(c.chosen),"0",token);m.click("Перенести");m.geometryReady();m.waitText("Изменения сохранены");m.check(m.treeToken(expected).equals(m.treeToken(r.load(store,id))),"explicit Move changes only original selected sources");r.sameAssets(r.load(store,id),assets);v.snapshot("chooser-saved",false);}
   else{m.click("Перенести");m.geometryReady();m.waitText("Проект изменился");v.snapshot("chooser-rejected",false);m.click("Понятно");c.identity(id,token);unchanged(store,id,newer,assets,prefs);c.rotate(UiAutomation.ROTATION_FREEZE_0,"chooser-stale-after-return",id,token,false);Map<String,?> now=c.prefs();m.click("Отмена");unchanged(store,id,newer,assets,now);}
  }dismissed();v.emit("CHOOSER_RESULT outcome="+outcome+" PASS");
 }finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void foreign(Object store)throws Exception{long source=c.insert(store),other=-1;try{Object doc=r.load(store,source);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));Object clone=r.parse(xml);m.assets(clone).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},clone,"QA_CHOOSER_FOREIGN");m.check(m.treeToken(doc).equals(m.treeToken(r.load(store,other))),"foreign chooser has identical XML");v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(other);v.rotate(UiAutomation.ROTATION_FREEZE_0);m.waitText("QA_ROTATE_OTHER");open(source);Map<String,?> prefs=c.prefs();final long target=other;m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",target)));Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"foreign chooser actually recreated");m.check((Long)m.managerField("project")==other&&m.managerField("chooserDraft")==null&&m.managerField("moveDraft")==null&&m.managerKeys("selected").isEmpty()&&"".equals(m.managerField("folder")),"foreign project keeps own root and drops chooser/source intent");v.snapshot("chooser-foreign",false);unchanged(store,source,xml,assets,prefs);unchanged(store,other,xml,assets,prefs);v.emit("CHOOSER_FOREIGN PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},source);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}
 void position(String stage)throws Exception{final AlertDialog dialog=(AlertDialog)m.managerField("chooserDialog");final int restoredFirst=(Integer)m.managerField("chooserFirst"),restoredTop=(Integer)m.managerField("chooserTop");final String[] value={""};m.runOnMainSync(()->{ListView list=dialog.getListView();value[0]="CHOOSER_POSITION stage="+stage+" orientation="+m.activity.getResources().getConfiguration().orientation+" first="+list.getFirstVisiblePosition()+" top="+(list.getChildCount()==0?0:list.getChildAt(0).getTop())+" count="+list.getAdapter().getCount()+" children="+list.getChildCount()+" height="+list.getHeight()+" selected="+list.getSelectedItemPosition()+" touch="+list.isInTouchMode()+" layoutRequested="+list.isLayoutRequested()+" restoredFirst="+restoredFirst+" restoredTop="+restoredTop;});v.emit(value[0]);}
 int first()throws Exception{final int[] index={-1};final AlertDialog dialog=(AlertDialog)m.managerField("chooserDialog");m.runOnMainSync(()->index[0]=dialog.getListView().getFirstVisiblePosition());return index[0];}
 void scroll(Object store)throws Exception{long id=c.insert(store);try{Object doc=r.load(store,id);Element root=(Element)m.call(doc,"root",new Class[]{});for(int i=0;i<18;i++)m.staticCall("ObjectTree","createFolder",new Class[]{Element.class,String.class,String.class,String.class},root,"",m.treeToken(doc),"QA_CHOOSER_DEST_"+i);m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,doc);open(id);byte[] xml=r.xml(r.load(store,id));String token=m.treeToken(r.load(store,id));Map<String,byte[]> assets=new HashMap<>(m.assets(r.load(store,id)));Map<String,?> prefs=c.prefs();final ListView options=((AlertDialog)m.managerField("chooserDialog")).getListView();position("before-set");m.runOnMainSync(()->options.setSelectionFromTop(6,0));position("after-set-immediate");m.waitForIdleSync();Thread.sleep(500);position("after-idle-500");v.snapshot("chooser-scroll-before",false);position("after-before-snapshot");m.check(first()==6,"long chooser really scrolled to option6 actual="+first());for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){Activity old=m.activity;v.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"scrolled chooser actually recreated");identity(id,token);position("after-recreate");v.controlReachable("Отмена");v.snapshot(direction==UiAutomation.ROTATION_FREEZE_90?"chooser-scroll-land":"chooser-scroll-return",false);position("after-recreate-snapshot");m.check(first()==6,"scrolled original option retained after rotation actual="+first());}m.click("Отмена");unchanged(store,id,xml,assets,prefs);dismissed();v.emit("CHOOSER_SCROLL PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void originFolder(Object store)throws Exception{long id=c.insert(store);try{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);m.waitText("QA_ROTATE_OTHER");m.click("QA_ROTATE_POINT");m.click("QA_ROTATE_OTHER");m.openManagerFolder("QA_ROTATE_FOLDER");Object doc=r.load(store,id);byte[] xml=r.xml(doc);String token=m.treeToken(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));Map<String,?> prefs=c.prefs();m.managerAction("Перенести выбранное");m.waitText("Перенести в папку");for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){Activity old=m.activity;v.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"source-folder chooser actually recreated");Object d=m.managerField("chooserDraft");Class<?> type=d.getClass();m.check(type.getField("project").getLong(d)==id&&token.equals(type.getField("token").get(d))&&type.getField("outside").getInt(d)==2&&Arrays.equals((int[])type.getMethod("indices").invoke(d),new int[]{2,3}),"source-folder chooser retains original hidden selection and token");m.check("0".equals(m.managerField("folder"))&&new HashSet<>(m.managerKeys("selected")).equals(c.chosen),"chooser keeps original browsing folder across both rotations");v.controlReachable("Отмена");}v.snapshot("chooser-source-folder-return",false);m.click("Отмена");unchanged(store,id,xml,assets,prefs);dismissed();v.emit("CHOOSER_ORIGIN_FOLDER PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());try{for(String outcome:new String[]{"cancel","choice-cancel","save","stale-before","stale-after"})scenario(store,outcome);foreign(store);originFolder(store);scroll(store);m.check(m.requests.get()==requests,"chooser and rotations issue no tile requests");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);m.call(store,"close",new Class[]{});}}
}
